DECLARE @gvDefaultId2 INT = (SELECT TOP 1 MaNguoiDung FROM NguoiDung WHERE TenDangNhap = N'tung.hoang');
IF @gvDefaultId2 IS NULL SET @gvDefaultId2 = (SELECT TOP 1 MaNguoiDung FROM NguoiDung WHERE MaVaiTro = 2);
IF @gvDefaultId2 IS NULL SET @gvDefaultId2 = 1;

SET IDENTITY_INSERT BaiHoc ON;
IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 27)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (27, 20, 1, @gvDefaultId2, N'Gia đình & Chị em gái (Nerry Describe Family)', N'Nghe',
            N'Luyện nghe miêu tả các thành viên trong gia đình qua lời giới thiệu chân thực của Neri.',
            N'<div class=''lesson-content''><h2>Gia đình & Miêu tả người thân (Describing Family & Relatives)</h2><p class=''lead''>Học cách miêu tả tuổi tác, ngoại hình, tính cách và mối quan hệ gắn bó giữa các thành viên trong gia đình thông qua câu chuyện giới thiệu chân thực của Neri.</p><h3>1. Từ vựng cốt lõi về Gia đình (Core Family Vocabulary)</h3><ul><li><strong>Thành viên trực hệ (Immediate Family):</strong> Parents (cha mẹ), Siblings (anh chị em ruột), Older brother (anh trai), Little sister / Younger sister (em gái).</li><li><strong>Miêu tả ngoại hình (Physical Appearance):</strong> Wavy brown hair (tóc nâu gợn sóng), Sparkling hazel eyes (đôi mắt màu nâu hạt dẻ sáng ngời), Spitting image of someone (bản sao / giống hệt ai đó).</li><li><strong>Tính cách & Phẩm chất (Personality Traits):</strong> Energetic (năng động), Extroverted (hướng ngoại), Creative (sáng tạo), Mediator (người hòa giải).</li></ul><h3>2. Kịch bản Transcript bài nghe hoàn chỉnh (Full Listening Transcript)</h3><div class=''dialogue-sample'' style=''background:#f8fafc; border:1px solid #e2e8f0; padding:15px; border-radius:6px; font-family:sans-serif;''><strong>Neri:</strong> "Hello everyone, my name is Neri and I am from Belize. Today, I would love to tell you all about my family. There are five members in my immediate family: my parents, my older brother, my younger sister, and myself.<br/><br/>The family member that I am closest to and going to describe in detail is my little sister, Maya. Maya is sixteen years old, which means she is four years younger than me. She is currently a sophomore in high school.<br/><br/>Appearance-wise, she has long wavy brown hair, sparkling hazel eyes, and a very warm, bright smile. People often say that she looks like a spitting image of our mother when she was young.<br/><br/>Personality-wise, Maya is remarkably energetic, extroverted, and creative. Unlike me, who prefers reading books quietly in my room, Maya loves outdoor sports and playing the acoustic guitar. She is also the mediator in our household whenever disagreements arise because of her patience and empathy. Even though we occasionally bicker over borrowing clothes, we share an unbreakable bond. I feel truly grateful to have such a supportive sibling in my life."</div></div>', 20, 20, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 28)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (28, 10, 1, @gvDefaultId2, N'Thì Hiện Tại Đơn & Ngôi Thứ 3 Số Ít (Third Person Singular)', N'NguPhap',
            N'Quy tắc thêm đuôi -s/-es, trợ động từ does/doesn''t và cách đặt câu hỏi thì hiện tại đơn.',
            N'<div class=''lesson-content''><h2>Thì Hiện Tại Đơn & Ngôi Thứ 3 Số Ít (Present Simple & 3rd Person Singular)</h2><p class=''lead''>Nắm vững cách chia động từ với các chủ ngữ ngôi thứ ba số ít (He, She, It, Danh từ số ít) - nền tảng ngữ pháp tối quan trọng trong giao tiếp tiếng Anh.</p><h3>1. Cấu trúc câu khẳng định với Ngôi thứ ba số ít</h3><p>Với chủ ngữ số ít (He, She, It, John, My mother), động từ nguyên thể bắt buộc phải thêm đuôi <strong>-s</strong> hoặc <strong>-es</strong>:</p><ul><li><strong>Quy tắc thông thường:</strong> Thêm <em>-s</em> vào sau động từ: work &rarr; works, read &rarr; reads, speak &rarr; speaks.</li><li><strong>Tận cùng là -o, -s, -ch, -x, -sh, -z:</strong> Thêm <em>-es</em>: go &rarr; goes, watch &rarr; watches, wash &rarr; washes, fix &rarr; fixes.</li><li><strong>Tận cùng là phụ âm + y:</strong> Đổi <em>y</em> thành <em>-ies</em>: study &rarr; studies, fly &rarr; flies. (Nhưng nguyên âm + y giữ nguyên: play &rarr; plays).</li><li><strong>Động từ bất quy tắc đặc biệt:</strong> have &rarr; <strong>has</strong>.</li></ul><h3>2. Dạng phủ định và Nghi vấn</h3><ul><li><strong>Phủ định:</strong> S + does not (doesn''t) + V_nguyên thể: <em>"She doesn''t eat meat on weekdays."</em></li><li><strong>Nghi vấn Yes/No:</strong> Does + S + V_nguyên thể?: <em>"Does he live near the city center? - Yes, he does."</em></li><li><strong>Câu hỏi Wh-:</strong> Wh-word + does + S + V_nguyên thể?: <em>"What time does your train arrive?"</em></li></ul></div>', 20, 20, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 29)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (29, 21, 2, @gvDefaultId2, N'Thể thao & Sở thích Giải trí (Watch Sport)', N'Nghe',
            N'Hội thoại nghe về các môn thể thao yêu thích, thói quen tập luyện và trận cầu đỉnh cao.',
            N'<div class=''lesson-content''><h2>Thể Thao & Sở Thích Giải Trí (Sports & Physical Fitness)</h2><p class=''lead''>Nâng cao kỹ năng nghe hiểu và vốn từ vựng về các môn thể thao phổ biến, giải đấu quốc tế và lợi ích của việc rèn luyện sức khỏe mỗi ngày.</p><h3>1. Từ vựng & Cụm từ thông dụng về Thể thao</h3><ul><li><strong>Môn thể thao & Hoạt động:</strong> Football / Soccer (bóng đá), Badminton (cầu lông), Swimming (bơi lội), Strength training (tập thể lực / gym), Full-body cardiovascular workout (bài tập tim mạch toàn thân).</li><li><strong>Thuật ngữ thi đấu:</strong> Champions League (Cúp C1 châu Âu), Header (cú đánh đầu ghi bàn), World-class performance (màn trình diễn đẳng cấp thế giới).</li><li><strong>Lợi ích sức khỏe:</strong> Relieve stress (giải tỏa căng thẳng), Boost mental focus (tăng cường sự tập trung trí não), Stay active (giữ lối sống năng động).</li></ul><h3>2. Kịch bản Transcript bài nghe hội thoại (Sports Conversation Transcript)</h3><div class=''dialogue-sample'' style=''background:#f8fafc; border:1px solid #e2e8f0; padding:15px; border-radius:6px; font-family:sans-serif;''><strong>Tom:</strong> "Hey Jessica, did you catch the Champions League football match on television last night?"<br/><br/><strong>Jessica:</strong> "I only managed to watch the second half because I was working late, but what an exhilarating game! That last-minute header was absolutely world-class."<br/><br/><strong>Tom:</strong> "I know, right? I was literally jumping out of my chair! Do you follow football regularly, or do you prefer playing sports yourself?"<br/><br/><strong>Jessica:</strong> "I enjoy watching major football tournaments, but when it comes to active participation, I am much more into badminton and swimming. I try to hit the local swimming pool at least three times a week before heading to the office."<br/><br/><strong>Tom:</strong> "That is really disciplined of you. Swimming is one of the best full-body cardiovascular exercises you can do. How long have you been swimming consistently?"<br/><br/><strong>Jessica:</strong> "For about four years now. It relieves stress remarkably well after a hectic day in front of computer screens. How about you, Tom? What sports do you do to keep fit?"<br/><br/><strong>Tom:</strong> "I play basketball with my college buddies every Saturday morning, and I do strength training at the gym twice a week. Staying physically active definitely boosts my mental focus and energy levels."<br/><br/><strong>Jessica:</strong> "Couldn''t agree more! We should organize a friendly badminton match with our colleagues sometime next weekend."<br/><br/><strong>Tom:</strong> "Count me in! That sounds like a wonderful plan."</div></div>', 20, 20, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 30)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (30, 4, 2, @gvDefaultId2, N'Du lịch Khám phá Việt Nam (Travelling Vietnam)', N'Doc',
            N'Bài đọc giới thiệu các địa danh du lịch nổi tiếng, văn hóa ẩm thực và thắng cảnh Việt Nam.',
            N'<div class=''lesson-content''><h2>Du Lịch & Thắng Cảnh Việt Nam (Exploring Vietnam''s Heritage)</h2><p class=''lead''>Rèn luyện kỹ năng đọc hiểu văn bản du lịch qua hành trình khám phá các di sản văn hóa, thắng cảnh thiên nhiên và phong tục ẩm thực dọc miền đất nước.</p><h3>1. Bài đọc học thuật: Hành trình qua miền di sản (Reading Passage)</h3><p>Vietnam is an enchanting destination in Southeast Asia that effortlessly bridges age-old historical charm with remarkable contemporary vitality. In the north, Hanoi captivates travelers with its labyrinthine Old Quarter, tranquil Hoan Kiem Lake, and savory culinary treasures such as Phở and Bún chả. A short distance east lies Ha Long Bay, an internationally celebrated UNESCO World Heritage site renowned for thousands of dramatic limestone karsts rising majestically above emerald waters.</p><p>Moving south into Central Vietnam, the imperial legacy of Hue and the enchanting ancient town of Hoi An offer unforgettable glimpses into traditional architecture and craftsmanship. Finally, the southern metropolis of Ho Chi Minh City pulses with vibrant commercial energy, modern skyscrapers, and an extraordinary street food scene that never sleeps.</p></div>', 25, 25, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 31)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (31, 23, 4, @gvDefaultId2, N'Câu Tường Thuật Chuyên Sâu (Reported Speech B2)', N'NguPhap',
            N'Quy tắc lùi thì, biến đổi trạng từ chỉ thời gian và reporting verbs học thuật nâng cao.',
            N'<div class=''lesson-content''><h2>Câu Tường Thuật Chuyên Sâu (Advanced Reported Speech B2)</h2><p class=''lead''>Nắm vững quy tắc chuyển đổi câu trực tiếp sang gián tiếp và làm chủ các động từ tường thuật phong phú (reporting verbs) chuẩn học thuật.</p><h3>1. Quy tắc lùi thì căn bản (Backshift of Tenses)</h3><ul><li>Hiện tại đơn &rarr; Quá khứ đơn (am/is/are &rarr; was/were, work &rarr; worked).</li><li>Hiện tại tiếp diễn &rarr; Quá khứ tiếp diễn (is working &rarr; was working).</li><li>Hiện tại hoàn thành & Quá khứ đơn &rarr; Quá khứ hoàn thành (have worked / worked &rarr; had worked).</li><li>Will &rarr; Would; Can &rarr; Could; May &rarr; Might; Must &rarr; Had to.</li></ul><h3>2. Biến đổi Trạng từ thời gian & Nơi chốn</h3><p>Today &rarr; that day; yesterday &rarr; the day before / the previous day; tomorrow &rarr; the following day / the next day; here &rarr; there; now &rarr; then; this &rarr; that.</p><h3>3. Các Động từ tường thuật chuyên sâu (Advanced Reporting Verbs)</h3><ul><li><strong>Verb + to V:</strong> agree, promise, threaten, offer, refuse. <em>("He refused to sign the revised contract.")</em></li><li><strong>Verb + O + to V:</strong> advise, encourage, remind, warn, urge. <em>("The doctor advised him to exercise regularly.")</em></li><li><strong>Verb + V-ing:</strong> admit, deny, suggest, recommend, apologize for. <em>("She denied disclosing confidential project data.")</em></li></ul></div>', 25, 25, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 32)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (32, 11, 4, @gvDefaultId2, N'Câu Bị Động Nâng Cao (Passive Voice B2)', N'NguPhap',
            N'Thể bị động đặc biệt, bị động với động từ tường thuật và cấu trúc nhờ bảo (causative).',
            N'<div class=''lesson-content''><h2>Câu Bị Động Nâng Cao & Cấu Trúc Khách Quan (Advanced Passive Voice)</h2><p class=''lead''>Nâng tầm diễn đạt học thuật với câu bị động khách quan (impersonal passive), thể nhờ bảo (causative) và bị động với động từ khuyết thiếu.</p><h3>1. Bị động với Động từ tường thuật / Quan điểm (Impersonal Passive)</h3><p>Dùng để trình bày thông tin một cách khách quan, khoa học trong văn phong học thuật và báo chí:</p><ul><li><strong>Cấu trúc 1:</strong> It + be + V3/ed (said / believed / reported / estimated) + that + S + V.<br/><em>Ví dụ: "It is estimated that global temperatures will rise by 1.5 degrees Celsius."</em></li><li><strong>Cấu trúc 2:</strong> S + be + V3/ed + to V (hoặc to have V3/ed nếu hành động xảy ra trước).<br/><em>Ví dụ: "The suspect is believed to have fled the country last night."</em></li></ul><h3>2. Thể nhờ bảo (Causative Form: Have / Get something done)</h3><ul><li><strong>Have something done:</strong> S + have + O(vật) + V3/ed: <em>"We are having our corporate server upgraded this weekend."</em></li><li><strong>Get someone to do something:</strong> S + get + O(người) + to V: <em>"The manager got the engineers to recheck the security audit."</em></li></ul></div>', 25, 25, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 33)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (33, 13, 4, @gvDefaultId2, N'Giao Tiếp & Viết Email Thương Mại B2 (Business Communication)', N'Doc',
            N'Kỹ năng đọc hiểu văn bản thương mại, soạn thảo email yêu cầu báo giá và xử lý khiếu nại.',
            N'<div class=''lesson-content''><h2>Giao Tiếp & Soạn Thảo Email Thương Mại Chuẩn B2 (Business Writing)</h2><p class=''lead''>Nắm bắt cấu trúc chuẩn quốc tế của email giao dịch thương mại: hỏi thông tin, đặt lịch hẹn, khiếu nại dịch vụ và đàm phán hợp đồng.</p><h3>1. Khung cấu trúc 4 phần của Business Email</h3><ul><li><strong>1. Subject Line (Tiêu đề):</strong> Cần rõ ràng, ngắn gọn và chứa mục đích chính: <em>"Inquiry regarding Enterprise Cloud Subscription - [Company Name]"</em>.</li><li><strong>2. Salutation (Chào đầu thư):</strong> <em>"Dear Mr. Peterson,"</em> hoặc <em>"Dear Ms. Davis,"</em> (Trang trọng), hoặc <em>"Dear Alex,"</em> (Bán trang trọng).</li><li><strong>3. Body Paragraphs (Thân thư):</strong> Nêu lý do gửi thư ở ngay câu mở đầu (<em>"I am writing to inquire about..."</em>), sau đó trình bày các điểm chính theo gạch đầu dòng hoặc đoạn văn súc tích.</li><li><strong>4. Call to Action & Sign-off (Kêu gọi hành động & Chào kết):</strong> <em>"Please let me know if you require any further documentation. Sincerely, / Best regards,"</em>.</li></ul></div>', 30, 30, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 34)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (34, 25, 4, @gvDefaultId2, N'Kỹ Năng Đàm Phán & Thuyết Trình Dự Án (Advanced Negotiation)', N'TuVung',
            N'Chiến lược đàm phán giá cả, thuyết phục đối tác đầu tư và chốt điều khoản hợp đồng.',
            N'<div class=''lesson-content''><h2>Kỹ Năng Đàm Phán & Thuyết Trình Pitching Dự Án Quốc Tế</h2><p class=''lead''>Làm chủ vốn từ vựng chuyên ngành đàm phán, kỹ thuật nhượng bộ có điều kiện và chiến lược thuyết phục hội đồng đầu tư.</p><h3>1. Thuật ngữ then chốt trong Đàm phán Doanh nghiệp</h3><ul><li><strong>BATNA (Best Alternative to a Negotiated Agreement):</strong> Phương án thay thế tối ưu nhất nếu đàm phán bất thành.</li><li><strong>Bargaining chips / Concessions:</strong> Những điều khoản nhượng bộ chiến lược nhằm đạt thỏa thuận lớn hơn.</li><li><strong>Win-win outcome:</strong> Kết quả đôi bên cùng có lợi bền vững.</li><li><strong>Counter-offer:</strong> Lời đề xuất phản hồi sau khi bác bỏ mức giá ban đầu của đối phương.</li></ul><h3>2. Các mẫu câu đàm phán chuyên nghiệp</h3><ul><li><em>"We would be prepared to accept your proposed delivery timeline, provided that you reduce the unit price by five percent."</em></li><li><em>"From our perspective, that condition represents a major compromise. Could we explore a phased rollout instead?"</em></li></ul></div>', 30, 30, 1);

IF NOT EXISTS (SELECT 1 FROM BaiHoc WHERE MaBaiHoc = 35)
    INSERT INTO BaiHoc (MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, TieuDe, LoaiBaiHoc, TomTat, NoiDung, ThoiGianUocTinhPhut, ThoiLuongUocTinh, DaXuatBan)
    VALUES (35, 19, 5, @gvDefaultId2, N'Đảo Ngữ & Cụm Từ Học Thuật C1 (C1 Inversion & Vocabulary)', N'NguPhap',
            N'Cấu trúc đảo ngữ nâng cao với trạng từ phủ định, đảo ngữ câu điều kiện và liên từ học thuật C1.',
            N'<div class=''lesson-content''><h2>Đảo Ngữ Nâng Cao & Cụm Từ Học Thuật Band C1 (Mastering Inversion)</h2><p class=''lead''>Đạt điểm số tối đa trong bài thi IELTS Writing Task 2 & Speaking Part 3 bằng cách vận dụng chuẩn xác các cấu trúc đảo ngữ tinh tế và từ vựng học thuật C1.</p><h3>1. Đảo ngữ với Trạng từ phủ định & Bán phủ định (Negative Adverbials)</h3><p>Khi trạng từ phủ định đứng đầu câu để nhấn mạnh, đảo trợ động từ lên trước chủ ngữ:</p><ul><li><strong>Never / Seldom / Rarely:</strong> <em>"Seldom has the global scientific community witnessed such rapid advancements in artificial intelligence."</em></li><li><strong>Not only ... but also:</strong> <em>"Not only did the startup exceed its initial quarterly revenue targets, but it also secured a lucrative international partnership."</em></li><li><strong>Hardly / Scarcely ... when / No sooner ... than:</strong> <em>"No sooner had the keynote speaker concluded his presentation than the audience erupted into applause."</em></li><li><strong>Only when / Only after:</strong> <em>"Only after conducting exhaustive clinical trials did the research team publish their conclusive findings."</em></li></ul><h3>2. Đảo ngữ Câu Điều Kiện (Inverted Conditionals)</h3><ul><li><strong>Loại 1 (Should):</strong> Should you experience any technical difficulties, please contact our support desk immediately.</li><li><strong>Loại 2 (Were):</strong> Were the government to allocate more resources to renewable infrastructure, carbon emissions would plummet significantly.</li><li><strong>Loại 3 (Had):</strong> Had they anticipated the sudden shift in consumer demand, the venture would not have suffered such heavy losses.</li></ul></div>', 35, 35, 1);

SET IDENTITY_INSERT BaiHoc OFF;
GO

